// SPI (Service Provider Interface) to wzorzec, w ktorym kod klienta zna WYLACZNIE interfejs
// uslugi i NIGDY nie pisze 'new KonkretnaImplementacja()' wprost w kodzie. Zamiast tego,
// implementacja jest ZNAJDOWANA DYNAMICZNIE w czasie dzialania programu (runtime), na
// podstawie pliku rejestracyjnego META-INF/services, a nie zaszyta na sztywno w kodzie zrodlowym
// (compile time). Rozni sie to od zwyklego 'new X()' tym, ze klient moze dzialac z ROZNYMI
// implementacjami bez ZADNEJ zmiany kodu - wystarczy podmienic JAR na classpath.

public interface PaymentService {
    String pay(double amount);
}

class CardPaymentService implements PaymentService {
    public String pay(double amount) { return "Zaplacono karta: " + amount; }
}
class CashPaymentService implements PaymentService {
    public String pay(double amount) { return "Zaplacono gotowka: " + amount; }
}

System.out.println(new CardPaymentService().pay(99.99));
System.out.println(new CashPaymentService().pay(99.99));

