static <T> T loadSingleProvider(Class<T> serviceInterface, ClassLoader loader) {
    return ServiceLoader.load(serviceInterface, loader).findFirst()
        .orElseThrow(() -> new IllegalStateException("Brak dostawcy dla " + serviceInterface));
}

