static void validate(String className, Class<?> serviceInterface, ClassLoader loader) {
    try {
        Class<?> clazz = Class.forName(className, false, loader);
        boolean implementsInterface = serviceInterface.isAssignableFrom(clazz);
        boolean hasNoArgCtor = java.util.Arrays.stream(clazz.getConstructors())
            .anyMatch(c -> c.getParameterCount() == 0);
        System.out.println(className + ": " + (implementsInterface && hasNoArgCtor ? "OK" : "BLAD"));
    } catch (ClassNotFoundException e) {
        System.out.println(className + ": BLAD (klasa nie istnieje)");
    }
}

interface MiniDriver { boolean accepts(String url); String connect(String url); }
class MiniProtocolDriver implements MiniDriver {
    public boolean accepts(String url) { return url.startsWith("mini://"); }
    public String connect(String url) { return "Polaczono przez MiniProtocolDriver: " + url; }
}
class TestProtocolDriver implements MiniDriver {
    public boolean accepts(String url) { return url.startsWith("test://"); }
    public String connect(String url) { return "Polaczono przez TestProtocolDriver: " + url; }
}

static String connect(String url) {
    for (MiniDriver d : ServiceLoader.load(MiniDriver.class)) {
        if (d.accepts(url)) return d.connect(url);
    }
    throw new IllegalArgumentException("Brak sterownika dla: " + url);
}
